{"status":200,"ok":true,"content_type":"text/javascript","size":497,"url":"http://localhost:8099/debug/src/cart.js","headers":{"content-length":"497","content-type":"text/javascript","date":"Mon, 28 Sep 2026 21:31:32 GMT","last-modified":"Mon, 28 Sep 2026 20:55:04 GMT","server":"SimpleHTTP/0.6 Python/3.11.2"},"body":"// Checkout cart: loads the cart from the API and renders its items.
async function loadCart() {
  const res = await fetch('/api/cart');
  const data = res.ok ? await res.json() : undefined;
  renderCart(data);
}

function renderCart(cart) {
  const list = document.querySelector('#items');
  for (const item of cart.items) {
    list.insertAdjacentHTML('beforeend', `<li>${item.name}<span>${item.price}</span></li>`);
  }
}

loadCart().catch((err) => console.error('Cart failed to load:', err));
"}

